import{_ as t,o as n,c as o,a3 as i}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Blueprint Compression and Production-Line Design Results","description":"","frontmatter":{"translationSource":{"title":"蓝图压缩与产线设计成果","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=t4CC9yDWIry334jvJw9Dqd","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/blueprint-compression-and-production-line-design-results"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/blueprint-compression-and-production-line-design-results"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/blueprint-compression-and-production-line-design-results"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/blueprint-compression-and-production-line-design-results"}]]},"headers":[],"relativePath":"blueprint-compression-and-production-line-design-results.md","filePath":"logistics/src/page-t4CC9yDWIry334jvJw9Dqd.md"}'),a={name:"blueprint-compression-and-production-line-design-results.md"};function r(s,e,d,l,p,u){return n(),o("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><h1 id="blueprint-compression-and-production-line-design-results" tabindex="-1">Blueprint Compression and Production-Line Design Results <a class="header-anchor" href="#blueprint-compression-and-production-line-design-results" aria-label="Permalink to &quot;Blueprint Compression and Production-Line Design Results&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-14. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>t4CC9yDWIry334jvJw9Dqd</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=t4CC9yDWIry334jvJw9Dqd" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>For convenience, this reference is included to make it easier to jump to <a href="/endfield-skydoc/factory-production-plans-logic-and-layout-implementation-across-versions">Research on Production Plans, Logic, and Layout Implementation for Each Version of Base Construction</a>.</p><p>In principle, the first half of this page should contain compressed modular production-line blueprint images and blueprint codes, together with the blueprint&#39;s effect and author. If the author cannot be traced, mark the author as <strong>Unknown Author</strong>. The second half can contain production-line designs.</p><p><span id="source-block-WeY8IOk8p864NNCg600NZb"></span></p><h2 id="standard-blueprints-general-production-conditions" tabindex="-1">Standard Blueprints (General Production Conditions <a class="header-anchor" href="#standard-blueprints-general-production-conditions" aria-label="Permalink to &quot;Standard Blueprints (General Production Conditions&quot;">​</a></h2><p><span id="source-block-l4MZ9YpUH8AsfLpkiBejAp"></span></p><h3 id="common-commonly-used-tags" tabindex="-1">Common/Commonly Used Tags <a class="header-anchor" href="#common-commonly-used-tags" aria-label="Permalink to &quot;Common/Commonly Used Tags&quot;">​</a></h3><p>No Stash: does not use a Stash; products are deposited through Depot Loaders.</p><p>Self-starting: refers to the initial input of value-adding loops such as the solid-gas transmutation of Xiranite into Xiragen and the seed-picking loop. The blueprint can automatically fetch goods from the depot and fill them in, requiring no manual filling by the player.</p><p>Pressurized depot input: products are deposited through multiple Depot Loaders so that the maximum deposit rate is higher than the production rate; during full-rate production, the backlog left in machines with empty storage can be slowly output to the depot and thereby reduced.</p><p>True/False %d%d (a string of digits): the blueprint&#39;s footprint; True means the pipes do not need to be routed via the storage line. For example, 5024 = a 50x24 footprint.</p><p>Conduit: conduits are used for liquid input and output between the inside and outside of the blueprint.</p><p>Compression ratio / space utilization: (required space: the sum of the volumes of the remaining machines after excluding logistics components, unrelated machines, and power-supply equipment) (occupied space: the maximum length times the maximum width of the module&#39;s footprint). The two ratios are reciprocals: usually &gt;1 means occupied space / required space, and &lt;1 means required space / occupied space. For a compression ratio &gt;1, a smaller number means better compression. The usual limit is 1.4–1.6; the more complex the module, the larger that limit.</p><p><span id="source-block-gLPzoNfu3gcpxzlDGlxGAx"></span></p><h2 id="special-blueprints-individual-blueprints-with-explanations" tabindex="-1">Special Blueprints (Individual Blueprints with Explanations <a class="header-anchor" href="#special-blueprints-individual-blueprints-with-explanations" aria-label="Permalink to &quot;Special Blueprints (Individual Blueprints with Explanations&quot;">​</a></h2><p><a href="/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals">Single-Pyro-Furnace Heavy Xiranite Plan Based on Clock Signals</a> · <a href="/endfield-skydoc/separator-core-module">Separator-Core Module</a></p></div>',1)])])}const m=t(a,[["render",r]]);export{h as __pageData,m as default};
